//! Port of `common/flash/FSWFStream.cpp`: the SWF byte/bit stream writer.
//!
//! `FSWFStream` (FSWFStream.h) is now a thin C++ shell over an opaque handle to the
//! [`Stream`] below (`flare_swfs_*`). The stream state of the C++ class -- the byte
//! vector with its trailing sentinel byte, `streamPos`, `bytePos`, `currentByte` and
//! the list of out-of-band "large data" blocks -- is kept bit for bit, so the
//! bit packing, endianness, tag headers and large-data splicing produce the same
//! bytes as the original (differential golden `swfwriter_cases.txt`, generated by
//! `tests/native/gen_swfwriter_cases.py`).
//!
//! Deviations from the C++ (only where the C++ was undefined behaviour or relied on a
//! different zlib):
//! * `WriteBits` with `size > 32` shifted by a negative count (UB; MinBits can ask for
//!   33/34 bits for a magnitude of 2^31). The size is clamped to 32 here.
//! * `WriteLargeData(NULL, n > 0)` crashed when the stream was written; the block is
//!   written as `n` zero bytes.
//! * `Append(self)` (a stream onto itself) is refused with an error status.
//! * `WriteToFileVersion6` on a buffer shorter than the 8 byte header read out of
//!   bounds; the buffer is returned unmodified (status 1).
//! * The zlib stream written by `WriteToFileVersion6` (default level 6) and by
//!   `FDTDefineBitsLossless*` (level 9) is produced by `miniz_oxide`, not by the zlib C
//!   library: it is a valid zlib stream that inflates to the same bytes but is not
//!   byte-identical to zlib's deflate output, and the "is it worth compressing"
//!   decision (`size > sizeOut + 8`) is taken on miniz's size.
//! * `MaxNum`/`MinBits` keep the x86 behaviour of `abs(INT_MIN)` (stays `INT_MIN`).

use std::collections::VecDeque;
use std::os::raw::c_void;

#[derive(Clone, Copy)]
struct LargeData {
    position: u32,
    data: *const u8,
    size: u32,
}

/// The state of the C++ `FSWFStream`.
#[derive(Clone)]
pub struct Stream {
    /// Always `stream_pos + 1` long: the C++ pushes a zero sentinel after every byte.
    stream: Vec<u8>,
    stream_pos: u32,
    /// Number of bits left to fill in the current byte.
    byte_pos: u32,
    current_byte: u8,
    out_data: VecDeque<LargeData>,
}

impl Default for Stream {
    fn default() -> Self {
        Self::new()
    }
}

impl Stream {
    pub fn new() -> Stream {
        let mut stream = Vec::with_capacity(1024);
        stream.push(0);
        Stream { stream, stream_pos: 0, byte_pos: 8, current_byte: 0, out_data: VecDeque::new() }
    }

    fn push_byte(&mut self) {
        self.stream[self.stream_pos as usize] = self.current_byte;
        self.stream_pos = self.stream_pos.wrapping_add(1);
        self.stream.push(0);
        self.current_byte = 0;
        self.byte_pos = 8;
    }

    /// `WriteBits(data, size)`: the low `size` bits of `data`, most significant first.
    pub fn write_bits(&mut self, data: u32, size: u32) {
        let mut size = size.min(32);
        while size != 0 {
            // data << (32 - size) >> (32 - bytePos); both shift counts are in 0..=31.
            let v = (data << (32 - size)) >> (32 - self.byte_pos);
            if size > self.byte_pos {
                self.current_byte |= v as u8;
                size -= self.byte_pos;
                self.push_byte();
            } else {
                self.current_byte |= v as u8;
                self.byte_pos -= size;
                size = 0;
                if self.byte_pos == 0 {
                    self.push_byte();
                }
            }
        }
    }

    /// `WriteLargeData`: remembers the block; the caller keeps ownership.
    pub fn write_large_data(&mut self, data: *const u8, size: u32) {
        self.out_data.push_back(LargeData { position: self.stream_pos, data, size });
    }

    pub fn flush_bits(&mut self) {
        if self.byte_pos != 8 {
            self.push_byte();
        }
    }

    pub fn write_dword(&mut self, data: u32) {
        self.flush_bits();
        self.write_bits(data & 0xff, 8);
        self.write_bits((data >> 8) & 0xff, 8);
        self.write_bits((data >> 16) & 0xff, 8);
        self.write_bits(data >> 24, 8);
    }

    pub fn write_word(&mut self, data: u32) {
        self.flush_bits();
        self.write_bits(data & 0xff, 8);
        self.write_bits((data >> 8) & 0xff, 8);
    }

    pub fn write_byte(&mut self, data: u32) {
        self.flush_bits();
        self.write_bits(data & 0xff, 8);
    }

    /// `Size()`: whole bytes in the stream plus every large block.
    pub fn size(&self) -> u32 {
        let mut size = self.stream_pos;
        for d in &self.out_data {
            size = size.wrapping_add(d.size);
        }
        size
    }

    /// `FullSize()`: the number of bytes `WriteToMemory` will produce.
    pub fn full_size(&self) -> u32 {
        let mut current: u32 = 0;
        let mut size: u32 = 0;
        for d in &self.out_data {
            if d.position.wrapping_sub(current) > 0 {
                size = size.wrapping_add(d.position.wrapping_sub(current));
            }
            current = d.position;
            size = size.wrapping_add(d.size);
        }
        if self.stream_pos > current {
            size = size.wrapping_add(self.stream_pos - current);
        }
        size
    }

    pub fn memory(&mut self) -> *mut u8 {
        self.stream.as_mut_ptr()
    }

    /// `Append(add)`: re-writes the whole bytes of `add` through `WriteBits` (so they join
    /// the current partial byte) and moves its large blocks over; `add` keeps its bytes.
    pub fn append(&mut self, add: &mut Stream) {
        let mut add_pos: i32 = 0;
        while let Some(d) = add.out_data.pop_front() {
            while add_pos < d.position as i32 {
                self.write_bits(add.stream[add_pos as usize] as u32, 8);
                add_pos += 1;
            }
            self.write_large_data(d.data, d.size);
        }
        while add_pos < add.stream_pos as i32 {
            self.write_bits(add.stream[add_pos as usize] as u32, 8);
            add_pos += 1;
        }
    }

    pub fn append_tag(&mut self, tag_id: u16, length: u32, buffer: Option<&mut Stream>) {
        let mut length = length;
        let mut long_length = 0;
        let mut long_head = false;
        if length > 62
            || (tag_id == 32 && length == 29)
            || (tag_id == 2 && length == 28)
            || (tag_id == 26 && length == 19)
        {
            long_head = true;
            long_length = length;
            length = 0x3f;
        }
        let first = (((tag_id as u32) << 6) | length) as u16;
        self.write_word(first as u32);
        if long_head {
            self.write_dword(long_length);
        }
        if let Some(b) = buffer {
            self.append(b);
        }
    }

    /// `WriteToMemory`: drains the large-data list. Returns false (after writing what
    /// fits) when `mem` is smaller than [`Stream::full_size`].
    pub fn write_to_memory(&mut self, mem: &mut [u8]) -> bool {
        let mut off: usize = 0;
        let mut current: u32 = 0;
        let mut ok = true;
        while let Some(d) = self.out_data.pop_front() {
            if d.position > current {
                let n = (d.position - current) as usize;
                ok &= copy_into(mem, &mut off, &self.stream[current as usize..current as usize + n]);
            }
            current = d.position;
            if d.size > 0 {
                if d.data.is_null() {
                    let n = d.size as usize;
                    if off + n <= mem.len() {
                        mem[off..off + n].fill(0);
                        off += n;
                    } else {
                        ok = false;
                    }
                } else {
                    // SAFETY: the C++ contract of WriteLargeData: `data` points to `size`
                    // readable bytes until the stream has been written.
                    let src = unsafe { std::slice::from_raw_parts(d.data, d.size as usize) };
                    ok &= copy_into(mem, &mut off, src);
                }
            }
        }
        if self.stream_pos > current {
            ok &= copy_into(mem, &mut off, &self.stream[current as usize..self.stream_pos as usize]);
        }
        ok
    }
}

fn copy_into(mem: &mut [u8], off: &mut usize, src: &[u8]) -> bool {
    if *off + src.len() > mem.len() {
        return false;
    }
    mem[*off..*off + src.len()].copy_from_slice(src);
    *off += src.len();
    true
}

/// `FSWFStream::MinBits`.
pub fn min_bits(number: u32, sign: u16) -> u32 {
    if number == 0 {
        return sign as u32;
    }
    let mut x: u32 = 1;
    let mut i: u32 = 1;
    while i < 33 {
        x <<= 1;
        if x > number {
            break;
        }
        i += 1;
    }
    i + sign as u32
}

/// `FSWFStream::MaxNum` (the `abs` of `INT_MIN` stays `INT_MIN`, compared as `int`).
pub fn max_num(a: i32, b: i32, c: i32, d: i32) -> u32 {
    let (a, b, c, d) = (a.wrapping_abs(), b.wrapping_abs(), c.wrapping_abs(), d.wrapping_abs());
    let r = if a > b {
        if a > c {
            if a > d {
                a
            } else {
                d
            }
        } else if c > d {
            c
        } else {
            d
        }
    } else if b > c {
        if b > d {
            b
        } else {
            d
        }
    } else if c > d {
        c
    } else {
        d
    };
    r as u32
}

/// zlib-format deflate through miniz (see the module note).
pub fn zlib_compress(data: &[u8], level: u8) -> Vec<u8> {
    miniz_oxide::deflate::compress_to_vec_zlib(data, level)
}

/// The tail of `WriteToFileVersion6` on an assembled `FWS` image: patches the version,
/// then either keeps it or returns `CWS` + header + deflated body. Returns `None` when
/// the image is shorter than the 8 byte header.
pub fn v6_pack(buf: &[u8]) -> Option<Vec<u8>> {
    let size = buf.len() as u32;
    if buf.len() < 8 {
        return None;
    }
    let mut img = buf.to_vec();
    img[3] = 6;
    let size_out_cap = (2.0 * ((size as f64 * 1.1) + 12.0)) as u32;
    let z = zlib_compress(&img[8..], 6);
    let size_out = if z.len() as u64 > size_out_cap as u64 { return Some(img) } else { z.len() as u32 };
    if size > size_out.wrapping_add(8) {
        let mut out = Vec::with_capacity(8 + z.len());
        out.extend_from_slice(&img[..8]);
        out[0] = b'C';
        out.extend_from_slice(&z);
        Some(out)
    } else {
        Some(img)
    }
}

// ---------------------------------------------------------------------------------------
// C ABI. The handle is a `Box<Stream>` leaked to C++; every entry point checks it for null
// and runs under `catch_unwind`. Status: 0 ok, 1 null/invalid argument, 2 panic, 3 buffer
// too small.

type H = *mut Stream;

unsafe fn with<R>(h: H, default: R, f: impl FnOnce(&mut Stream) -> R) -> R {
    if h.is_null() {
        return default;
    }
    crate::guard(default, || f(&mut *h))
}

/// Allocates an empty stream, or NULL.
#[no_mangle]
pub extern "C" fn flare_swfs_new() -> *mut c_void {
    crate::guard(std::ptr::null_mut(), || Box::into_raw(Box::new(Stream::new())) as *mut c_void)
}

/// # Safety
/// `h` must be NULL or a handle from `flare_swfs_new`/`flare_swfs_clone`, freed once.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_free(h: *mut c_void) {
    if !h.is_null() {
        crate::guard((), || drop(Box::from_raw(h as H)));
    }
}

/// Copy of the whole state (bytes, partial byte, large-data list); NULL on failure.
///
/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_clone(h: *const c_void) -> *mut c_void {
    if h.is_null() {
        return std::ptr::null_mut();
    }
    crate::guard(std::ptr::null_mut(), || Box::into_raw(Box::new((*(h as *const Stream)).clone())) as *mut c_void)
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_bits(h: *mut c_void, data: u32, size: u32) -> i32 {
    with(h as H, 1, |s| {
        s.write_bits(data, size);
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle; `data` must stay valid for `size` bytes until the
/// stream has been written (ownership is not transferred).
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_large_data(h: *mut c_void, data: *const u8, size: u32) -> i32 {
    with(h as H, 1, |s| {
        s.write_large_data(data, size);
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_flush_bits(h: *mut c_void) -> i32 {
    with(h as H, 1, |s| {
        s.flush_bits();
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_dword(h: *mut c_void, data: u32) -> i32 {
    with(h as H, 1, |s| {
        s.write_dword(data);
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_word(h: *mut c_void, data: u32) -> i32 {
    with(h as H, 1, |s| {
        s.write_word(data);
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_byte(h: *mut c_void, data: u32) -> i32 {
    with(h as H, 1, |s| {
        s.write_byte(data);
        0
    })
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_size(h: *mut c_void) -> u32 {
    with(h as H, 0, |s| s.size())
}

/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_full_size(h: *mut c_void) -> u32 {
    with(h as H, 0, |s| s.full_size())
}

/// Origin of the byte vector (valid until the next write); NULL for a NULL handle.
///
/// # Safety
/// `h` must be NULL or a live handle.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_memory(h: *mut c_void) -> *mut u8 {
    with(h as H, std::ptr::null_mut(), |s| s.memory())
}

/// # Safety
/// `h` and `add` must be NULL or live handles.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_append(h: *mut c_void, add: *mut c_void) -> i32 {
    if h.is_null() || add.is_null() || h == add {
        return 1;
    }
    crate::guard(2, || {
        (*(h as H)).append(&mut *(add as H));
        0
    })
}

/// `body` may be NULL (tag without body).
///
/// # Safety
/// `h` and `body` must be NULL or live handles.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_append_tag(h: *mut c_void, tag_id: u16, length: u32, body: *mut c_void) -> i32 {
    if h.is_null() || h == body {
        return 1;
    }
    crate::guard(2, || {
        let b = if body.is_null() { None } else { Some(&mut *(body as H)) };
        (*(h as H)).append_tag(tag_id, length, b);
        0
    })
}

/// Writes `Size()`-many... precisely `FullSize()` bytes into `mem` (capacity `cap`) and
/// drains the large-data list. Status 3 when `cap` is too small.
///
/// # Safety
/// `h` must be NULL or a live handle; `mem` must be valid for `cap` bytes; large blocks
/// must still be readable.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_write_to_memory(h: *mut c_void, mem: *mut u8, cap: u32) -> i32 {
    if h.is_null() || (mem.is_null() && cap > 0) {
        return 1;
    }
    crate::guard(2, || {
        let out: &mut [u8] = if cap == 0 { &mut [] } else { std::slice::from_raw_parts_mut(mem, cap as usize) };
        if (*(h as H)).write_to_memory(out) {
            0
        } else {
            3
        }
    })
}

#[no_mangle]
pub extern "C" fn flare_swfs_min_bits(number: u32, sign: u16) -> u32 {
    crate::guard(0, || min_bits(number, sign))
}

#[no_mangle]
pub extern "C" fn flare_swfs_max_num(a: i32, b: i32, c: i32, d: i32) -> u32 {
    crate::guard(0, || max_num(a, b, c, d))
}

/// `WriteToFileVersion6` after the image has been assembled: writes the bytes to put in the
/// file to `out` (capacity `out_cap` >= `size`) and their count to `*out_len`.
/// Status 1 (image copied unchanged) when `size < 8`.
///
/// # Safety
/// `buf` valid for `size` bytes, `out` for `out_cap` bytes, `out_len` for one `u32`.
#[no_mangle]
pub unsafe extern "C" fn flare_swfs_v6_pack(buf: *const u8, size: u32, out: *mut u8, out_cap: u32, out_len: *mut u32) -> i32 {
    if out_len.is_null() || (size > 0 && (buf.is_null() || out.is_null())) || out_cap < size {
        return 1;
    }
    *out_len = 0;
    crate::guard(2, || {
        let src: &[u8] = if size == 0 { &[] } else { std::slice::from_raw_parts(buf, size as usize) };
        let (res, status) = match v6_pack(src) {
            Some(v) => (v, 0),
            None => (src.to_vec(), 1),
        };
        if res.len() > out_cap as usize {
            return 3;
        }
        if !res.is_empty() {
            std::slice::from_raw_parts_mut(out, res.len()).copy_from_slice(&res);
        }
        *out_len = res.len() as u32;
        status
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bytes(s: &mut Stream) -> Vec<u8> {
        let mut v = vec![0u8; s.full_size() as usize];
        assert!(s.write_to_memory(&mut v));
        v
    }

    #[test]
    fn bit_packing_is_msb_first_and_pads_with_zero() {
        let mut s = Stream::new();
        s.write_bits(0b101, 3);
        s.write_bits(0b11, 2);
        s.flush_bits();
        assert_eq!(bytes(&mut s), vec![0b1011_1000]);
        let mut s = Stream::new();
        s.write_bits(0x1ff, 9); // 9 ones across a byte boundary
        s.write_bits(0, 3);
        s.flush_bits();
        assert_eq!(bytes(&mut s), vec![0xff, 0x80]);
    }

    #[test]
    fn words_are_little_endian_and_flush_first() {
        let mut s = Stream::new();
        s.write_bits(1, 1);
        s.write_word(0x1234);
        s.write_dword(0xA1B2C3D4);
        s.write_byte(0x1ff);
        assert_eq!(bytes(&mut s), vec![0x80, 0x34, 0x12, 0xD4, 0xC3, 0xB2, 0xA1, 0xff]);
    }

    #[test]
    fn size_and_large_data_splice() {
        let blob = [9u8, 8, 7];
        let mut s = Stream::new();
        s.write_byte(1);
        s.write_large_data(blob.as_ptr(), 3);
        s.write_byte(2);
        assert_eq!(s.size(), 5);
        assert_eq!(s.full_size(), 5);
        assert_eq!(bytes(&mut s), vec![1, 9, 8, 7, 2]);
        // the list is drained: a second write only has the plain bytes
        assert_eq!(s.full_size(), 2);
        assert_eq!(s.size(), 2);
        assert_eq!(bytes(&mut s), vec![1, 2]);
    }

    #[test]
    fn append_joins_the_partial_byte_and_moves_blobs() {
        let blob = [0xAAu8];
        let mut body = Stream::new();
        body.write_byte(0xF0);
        body.write_large_data(blob.as_ptr(), 1);
        body.write_byte(0x0F);
        let mut s = Stream::new();
        s.write_bits(0b1, 1);
        s.append(&mut body);
        s.flush_bits();
        // 1 | 11110000 -> 0xF8 0x00 .. the bytes keep flowing through the open byte
        assert_eq!(s.size(), 4);
        assert_eq!(bytes(&mut s), vec![0xF8, 0xAA, 0x07, 0x80]);
        assert!(body.out_data.is_empty());
    }

    #[test]
    fn tag_headers() {
        let mut body = Stream::new();
        body.write_word(7);
        let mut s = Stream::new();
        s.append_tag(6, body.size(), Some(&mut body));
        assert_eq!(bytes(&mut s), vec![(6 << 6 | 2) as u8, 0x01, 7, 0]);
        // long form forced by length > 62 and by the three special pairs
        for (id, len) in [(6u16, 63u32), (32, 29), (2, 28), (26, 19)] {
            let mut s = Stream::new();
            s.append_tag(id, len, None);
            let b = bytes(&mut s);
            assert_eq!(b.len(), 6, "{id} {len}");
            assert_eq!(u16::from_le_bytes([b[0], b[1]]), (id << 6) | 0x3f);
            assert_eq!(u32::from_le_bytes([b[2], b[3], b[4], b[5]]), len);
        }
    }

    #[test]
    fn min_bits_and_max_num() {
        assert_eq!(min_bits(0, 0), 0);
        assert_eq!(min_bits(0, 1), 1);
        assert_eq!(min_bits(1, 0), 1);
        assert_eq!(min_bits(1, 1), 2);
        assert_eq!(min_bits(255, 1), 9);
        assert_eq!(min_bits(256, 0), 9);
        assert_eq!(min_bits(0x7fff_ffff, 1), 32);
        assert_eq!(min_bits(0x8000_0000, 0), 33);
        assert_eq!(max_num(1, -5, 3, 2), 5);
        assert_eq!(max_num(-7, 5, 3, 2), 7);
        assert_eq!(max_num(1, 2, -9, 4), 9);
        assert_eq!(max_num(0, 0, 0, -3), 3);
        assert_eq!(max_num(i32::MIN, 1, 2, 3), 3); // abs(INT_MIN) stays negative
    }

    #[test]
    fn v6_pack_compresses_only_when_it_pays() {
        let mut img = b"FWS\x04".to_vec();
        img.extend_from_slice(&0u32.to_le_bytes());
        img.extend_from_slice(&[0u8; 4000]);
        let n = img.len() as u32;
        img[4..8].copy_from_slice(&n.to_le_bytes());
        let out = v6_pack(&img).unwrap();
        assert_eq!(&out[..4], b"CWS\x06");
        assert_eq!(&out[4..8], &n.to_le_bytes());
        assert_eq!(miniz_oxide::inflate::decompress_to_vec_zlib(&out[8..]).unwrap(), vec![0u8; 4000]);
        // incompressible tiny body stays FWS, version patched
        let img = b"FWS\x04\x0b\0\0\0abc".to_vec();
        let out = v6_pack(&img).unwrap();
        assert_eq!(out, b"FWS\x06\x0b\0\0\0abc".to_vec());
        assert!(v6_pack(b"FWS").is_none());
    }

    #[test]
    fn ffi_null_and_size_checks() {
        unsafe {
            assert_eq!(flare_swfs_write_bits(std::ptr::null_mut(), 1, 1), 1);
            let h = flare_swfs_new();
            assert!(!h.is_null());
            assert_eq!(flare_swfs_append(h, h), 1);
            assert_eq!(flare_swfs_append_tag(h, 1, 0, h), 1);
            flare_swfs_write_word(h, 0xBEEF);
            let c = flare_swfs_clone(h);
            flare_swfs_write_byte(h, 1);
            assert_eq!(flare_swfs_full_size(h), 3);
            assert_eq!(flare_swfs_full_size(c), 2); // independent copy
            let mut small = [0u8; 2];
            assert_eq!(flare_swfs_write_to_memory(h, small.as_mut_ptr(), 2), 3);
            let mut ok = [0u8; 2];
            assert_eq!(flare_swfs_write_to_memory(c, ok.as_mut_ptr(), 2), 0);
            assert_eq!(ok, [0xEF, 0xBE]);
            assert_eq!(flare_swfs_write_to_memory(c, std::ptr::null_mut(), 4), 1);
            assert_eq!(*flare_swfs_memory(h).as_ref().expect("null"), 0xEF);
            let mut out_len = 7u32;
            assert_eq!(flare_swfs_v6_pack(std::ptr::null(), 4, std::ptr::null_mut(), 4, &mut out_len), 1);
            flare_swfs_free(h);
            flare_swfs_free(c);
            flare_swfs_free(std::ptr::null_mut());
        }
    }

    // ---- replay of the cases recorded from the original C++ (swfwriter_cases.txt) ----

    #[derive(Debug)]
    enum Op {
        Bits(u32, u32),
        Dword(u32),
        Word(u32),
        Byte(u32),
        Flush,
        Large(u32, u32),
        NoBody(u16, u32),
        Append(Vec<Op>),
        Tag(u16, Vec<Op>),
    }

    fn parse_ops(toks: &mut std::iter::Peekable<std::slice::Iter<&str>>) -> Vec<Op> {
        let mut ops = Vec::new();
        while let Some(&&t) = toks.peek() {
            if t == "]" {
                toks.next();
                break;
            }
            toks.next();
            if t == "-" {
                continue; // an empty op list
            }
            let p: Vec<&str> = t.trim_end_matches('[').split(':').collect();
            let n = |i: usize| p[i].parse::<u32>().unwrap();
            ops.push(match p[0] {
                "b" => Op::Bits(n(1), n(2)),
                "d" => Op::Dword(n(1)),
                "w" => Op::Word(n(1)),
                "y" => Op::Byte(n(1)),
                "f" => Op::Flush,
                "L" => Op::Large(n(1), n(2)),
                "N" => Op::NoBody(n(1) as u16, n(2)),
                "A" => Op::Append(parse_ops(toks)),
                "T" => Op::Tag(n(1) as u16, parse_ops(toks)),
                other => panic!("bad op {other}"),
            });
        }
        ops
    }

    fn parse(text: &str) -> Vec<Op> {
        if text == "-" {
            return vec![];
        }
        let toks: Vec<&str> = text.split_whitespace().collect();
        parse_ops(&mut toks.iter().peekable())
    }

    fn exec(s: &mut Stream, ops: &[Op], blobs: &mut Vec<Box<[u8]>>, mut trace: Option<&mut String>) {
        for o in ops {
            match o {
                Op::Bits(a, b) => s.write_bits(*a, *b),
                Op::Dword(a) => s.write_dword(*a),
                Op::Word(a) => s.write_word(*a),
                Op::Byte(a) => s.write_byte(*a),
                Op::Flush => s.flush_bits(),
                Op::Large(len, seed) => {
                    let v: Vec<u8> = (0..*len).map(|i| seed.wrapping_add(i.wrapping_mul(7)) as u8).collect();
                    blobs.push(v.into_boxed_slice());
                    let b = blobs.last().unwrap();
                    s.write_large_data(b.as_ptr(), *len);
                }
                Op::NoBody(id, len) => s.append_tag(*id, *len, None),
                Op::Append(sub) => {
                    let mut x = Stream::new();
                    exec(&mut x, sub, blobs, None);
                    s.append(&mut x);
                    if let Some(t) = trace.as_deref_mut() {
                        t.push_str(&format!("s{};", x.size()));
                    }
                }
                Op::Tag(id, sub) => {
                    let mut body = Stream::new();
                    exec(&mut body, sub, blobs, None);
                    let n = body.size();
                    s.append_tag(*id, n, Some(&mut body));
                }
            }
            if let Some(t) = trace.as_deref_mut() {
                t.push_str(&format!("{},", s.size()));
            }
        }
    }

    fn hex(v: &[u8]) -> String {
        if v.is_empty() {
            "-".into()
        } else {
            v.iter().map(|b| format!("{b:02x}")).collect()
        }
    }

    fn unhex(s: &str) -> Vec<u8> {
        if s == "-" {
            return vec![];
        }
        (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
    }

    #[test]
    fn replay_recorded_cpp_stream_cases() {
        let mut counts = std::collections::BTreeMap::<&str, usize>::new();
        for line in include_str!("swfwriter_cases.txt").lines() {
            let f: Vec<&str> = line.split('|').collect();
            match f[0] {
                "stream" => {
                    let mut blobs = Vec::new();
                    let mut s = Stream::new();
                    let mut trace = String::new();
                    exec(&mut s, &parse(f[1]), &mut blobs, Some(&mut trace));
                    assert_eq!(trace, f[2], "{line}");
                    assert_eq!(s.size().to_string(), f[3], "{line}");
                    assert_eq!(s.full_size().to_string(), f[4], "{line}");
                    assert_eq!(hex(&bytes(&mut s)), f[5], "{line}");
                }
                "streamcopy" => {
                    let mut blobs = Vec::new();
                    let mut s = Stream::new();
                    exec(&mut s, &parse(f[1]), &mut blobs, None);
                    let mut c = s.clone();
                    let mut d = Stream::new();
                    d.write_byte(9);
                    d = s.clone();
                    exec(&mut s, &parse(f[2]), &mut blobs, None);
                    assert_eq!(hex(&bytes(&mut s)), f[3], "{line}");
                    assert_eq!(hex(&bytes(&mut c)), f[4], "{line}");
                    assert_eq!(hex(&bytes(&mut d)), f[5], "{line}");
                }
                "minbits" => {
                    let (n, sg): (u32, u16) = (f[1].parse().unwrap(), f[2].parse().unwrap());
                    assert_eq!(min_bits(n, sg).to_string(), f[3], "{line}");
                }
                "maxnum" => {
                    let v: Vec<i32> = f[1..5].iter().map(|x| x.parse().unwrap()).collect();
                    assert_eq!(max_num(v[0], v[1], v[2], v[3]).to_string(), f[5], "{line}");
                }
                "v6" => {
                    let image = unhex(f[3]);
                    let packed = v6_pack(&image).unwrap();
                    let comp = packed[0] == b'C';
                    assert_eq!(comp, f[4] == "1", "compress decision differs: {line}");
                    assert_eq!(hex(&packed[..8]), f[5], "{line}");
                    let payload = if comp {
                        miniz_oxide::inflate::decompress_to_vec_zlib(&packed[8..]).unwrap()
                    } else {
                        packed[8..].to_vec()
                    };
                    assert_eq!(hex(&payload), f[6], "{line}");
                }
                _ => continue,
            }
            *counts.entry(f[0]).or_default() += 1;
        }
        assert_eq!(counts["stream"], 210);
        assert_eq!(counts["streamcopy"], 12);
        assert_eq!(counts["minbits"], 52);
        assert_eq!(counts["maxnum"], 200);
        assert_eq!(counts["v6"], 40);
    }
}
